#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Build the dependency-free Bittray corporate site from editable content."""
import json
import shutil
from pathlib import Path
from html import escape as e

ROOT = Path(__file__).resolve().parent
OUT = ROOT.parent if ROOT.name == 'source' else ROOT / 'dist'
OUT.mkdir(exist_ok=True)
SERVICES = json.loads((ROOT / 'services.json').read_text())
if (ROOT/'extra-services.json').exists():
    SERVICES += json.loads((ROOT/'extra-services.json').read_text())
EXPANDED = {}
for extra in ROOT.glob('expanded-*.json'):
    EXPANDED.update({k:v for k,v in json.loads(extra.read_text()).items() if not k.startswith('_')})
for service in SERVICES:
    if service['id'] in EXPANDED:
        service['intro'] = EXPANDED[service['id']]['intro']
INDUSTRIES = json.loads((ROOT / 'industries.json').read_text())
APPROACH = json.loads((ROOT / 'approach.json').read_text())
BASE = 'https://vsvld778.github.io/bittray-website/v3/'
LABELS = {s['id']: s['label'] for s in SERVICES}
SHORT = {
 'integration': ('Интеграция систем', 'Связать приложения, данные и подразделения в управляемый процесс.', ['Обмен данными', 'Интерфейсы и API', 'Справочники и события']),
 'security': ('Безопасность предприятия', 'Согласовать защиту информации, доступ и обработку событий.', ['Информационная безопасность', 'Производственная среда', 'Системы объекта']),
 'crm': ('CRM и клиентские процессы', 'Объединить обращения, продажи, задачи и историю клиента.', ['Продажи и сервис', 'Маршруты согласований', 'Связь с учётом']),
 'erp': ('ERP и управление ресурсами', 'Согласовать планирование, закупки, склад, производство и финансы.', ['Ресурсы и операции', 'Единые справочники', 'Управленческие данные']),
 'vision': ('Компьютерное зрение', 'Превратить изображения и видео в события для рабочих процессов.', ['Визуальный контроль', 'Проверка гипотез', 'Интеграция аналитики']),
 'audit': ('Обследование и проектирование', 'Разобраться в процессах, описать требования и спроектировать целевую систему.', ['Карта систем', 'Архитектура', 'План внедрения']),
 'support': ('Сопровождение и развитие', 'Поддерживать работу решения и управлять его изменениями после запуска.', ['Обращения и инциденты', 'Обновления', 'Развитие функций'])
}

def ul(items, cls='check-list'):
    return '<ul class="'+cls+'">'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'

def icon(name='arrow'):
    paths = {'arrow': '<path d="M5 12h14M13 6l6 6-6 6"/>', 'menu': '<path d="M4 7h16M4 12h16M4 17h16"/>'}
    return '<svg class="ui-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+paths[name]+'</svg>'

def link(url, label, cls='text-link'):
    return f'<a class="{cls}" href="{url}"><span>{e(label)}</span> {icon()}</a>'

def nav(active, current):
    items=[('solutions','Решения'),('industries','Отрасли'),('approach','Подход'),('knowledge','Материалы'),('about','Компания'),('contacts','Контакты')]
    links=''.join(f'<a href="{key}.html"'+(' aria-current="page"' if current==key else (' class="is-active"' if active==key else ''))+'><span>'+label+'</span>'+icon()+'</a>' for key,label in items)
    return '<header class="site-header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="БитТрай — главная"><img src="bittray-logo.svg" alt="БитТрай" width="58" height="72"><span class="brand-caption">Технологии.<br>Системы. Взаимодействие.</span></a><a class="header-phone" href="tel:+74957609487">+7 (495) 760-94-87</a><button class="menu-toggle" type="button" data-menu-toggle aria-controls="main-nav" aria-expanded="false"><span>Меню</span><span class="menu-lines" aria-hidden="true"></span></button></div><nav class="main-nav" id="main-nav" aria-label="Основная навигация"><div class="container nav-grid">'+links+'<div class="nav-meta"><span>Системная интеграция · Разработка · Безопасность</span>'+link('contacts.html','Обсудить задачу','text-link')+'</div></div></nav></header>'

def footer():
    return '<footer class="site-footer"><div class="container footer-grid"><div><a class="brand" href="index.html"><img src="bittray-logo.svg" alt="БитТрай" width="58" height="72"></a><p>Мы с Вами —<br>с начала и навсегда!</p><p class="small">ООО «БитТрай»<br>Работаем с 2019 года · Москва</p></div><div><h3>Направления</h3><ul class="link-list">'+''.join(f'<li><a href="{s["id"]}.html">{e(s["label"])}</a></li>' for s in SERVICES)+'</ul></div><div><h3>О проекте</h3><ul class="link-list"><li><a href="industries.html">Отраслевые сценарии</a></li><li><a href="approach.html">Этапы работы</a></li><li><a href="knowledge.html">Полезные материалы</a></li><li><a href="about.html">О компании</a></li><li><a href="contacts.html">Контакты</a></li></ul></div><div><h3>Начать разговор</h3><p><a href="tel:+74957609487">+7 (495) 760-94-87</a></p><p><a href="mailto:bittray.dv@yandex.ru">bittray.dv@yandex.ru</a></p><p class="small">Расскажите о задаче и действующих системах. Поможем определить следующий шаг.</p></div></div><div class="container footer-bottom"><span>© БитТрай, 2019–2026</span><a href="contacts.html#brief">Подготовить описание проекта ↗</a></div></footer>'

def cta(direction=''):
    return '<section class="cta-band"><div class="container split"><div><span class="eyebrow">Следующий шаг</span><h2>Начнём с вашей задачи.</h2><p>Для первого разговора достаточно описать процесс, проблему и желаемый результат.</p></div>'+link('contacts.html'+('?direction='+direction if direction else '')+'#brief','Обсудить проект','button button-light')+'</div></section>'

def page(name, title, description, body, active=None):
    canonical=BASE+(name+'.html' if name!='index' else '')
    html='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#28243c"><title>'+e(title)+' — БитТрай</title><meta name="description" content="'+e(description,quote=True)+'"><meta property="og:title" content="'+e(title,quote=True)+' — БитТрай"><meta property="og:description" content="'+e(description,quote=True)+'"><meta property="og:type" content="website"><meta property="og:locale" content="ru_RU"><link rel="canonical" href="'+canonical+'"><link rel="icon" type="image/svg+xml" href="bittray-logo.svg"><link rel="stylesheet" href="styles.css?v=reference-2"><link rel="stylesheet" href="interiors.css?v=reference-2"><script defer src="app.js?v=reference-2"></script></head><body data-page="'+name+'"><a class="skip-link" href="#main">Перейти к содержанию</a>'+nav(active or name, name)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
    (OUT/(name+'.html')).write_text(html,encoding='utf-8')

def heading(kicker, title, intro='', id=''):
    return f'<div class="section-heading"'+(f' id="{id}"' if id else '')+f'><span class="eyebrow">{e(kicker)}</span><h2>{e(title)}</h2>'+(f'<p class="section-intro">{e(intro)}</p>' if intro else '')+'</div>'

def pagehero(kicker,title,intro,parent=None,aside=''):
    crumbs='<a href="index.html">Главная</a><span aria-hidden="true">/</span>'
    if parent: crumbs+='<a href="solutions.html">Решения</a><span aria-hidden="true">/</span>'
    crumbs+=f'<span>{e(kicker)}</span>'
    return '<section class="page-hero"><div class="container"><nav class="breadcrumbs" aria-label="Хлебные крошки">'+crumbs+'</nav><div class="page-intro-grid"><div><span class="eyebrow">'+e(kicker)+'</span><h1>'+e(title)+'</h1><p class="lead">'+e(intro)+'</p></div>'+aside+'</div></div></section>'

def cards(items, cls='feature-grid'):
    return '<div class="'+cls+'">'+''.join('<article class="feature-card"><h3>'+e(x['title'])+'</h3><p>'+e(x['text'])+'</p></article>' for x in items)+'</div>'

def solutioncards(home=False):
    result='<div class="solution-grid">'
    for i,s in enumerate(SERVICES):
        sid=s['id'];title,desc,tags=SHORT[sid]
        result+=f'<article class="service-card'+(' featured' if home and i==0 else '')+f'" data-solution data-search="{e(title+" "+desc+" "+" ".join(tags),quote=True)}"><div class="service-card-head"><span class="card-number">0{i+1}</span><span>{e(s["category"])}</span></div><h3><a href="{sid}.html">{e(title)}</a></h3><p>{e(desc)}</p>'+ul(tags,'tags')+link(sid+'.html','Подробнее о решении')+'</article>'
    return result+'</div>'

